#!/usr/bin/env python3
"""docs/relatorio-original.md: analise ponto a ponto das alegacoes do 'Relatorio Pericial Independente'.
Uso: python -I 03c_relatorio_original.py DIR_FASE2 DIR_ALEG RAIZ"""
import os, sys
import pandas as pd
R, AL, RAIZ = sys.argv[1], sys.argv[2], sys.argv[3]
rd = lambda b, f: pd.read_csv(os.path.join(b, f)) if os.path.exists(os.path.join(b, f)) else None
def n(x, d=0):
    s = f"{x:,.{d}f}"; return s.replace(",", "X").replace(".", ",").replace("X", ".")
cru = rd(R, "H3_h3_recontagem_relogio_cru.csv"); tot = rd(R, "H2_h2_totais_absolutos.csv").set_index(["ano", "turno"])
apt = rd(AL, "ALEG_aptos_secoes_tardias.csv").iloc[0]; uf = rd(AL, "ALEG_tardias_por_uf.csv").set_index("uf"); un = rd(AL, "ALEG_unanimes.csv").set_index("ano")
a5n = rd(R, "A5_a5_estimativa_nacional_votos_apos_nominal.csv"); a5m = rd(R, "A5_a5_liberacao_manual_total.csv"); h4 = rd(R, "H4_h4_coef.csv")
reg = rd(R, "registro_testes.csv")
c = lambda a, t, col: int(cru[(cru.ano == a) & (cru.turno == t) & (cru.recorte == "com exterior")][col].iloc[0])
h4l = h4[(h4.L == 115) & (h4.spec == "2026 T2 c/ lag")].iloc[0]
L = ["# O \"Relatório Pericial Independente\" original, ponto a ponto\n"]
L.append("> **Limite desta página.** O texto do documento original (8 páginas, anônimo) não foi fornecido a esta sessão. As alegações abaixo vêm do **resumo** preparado numa sessão anterior. Alegações que não constem dele não foram avaliadas. Se o PDF for entregue, esta página deve ser revisada contra o texto.\n")
L.append("Critério da coluna \"Reproduz?\": **sim** = o número do relatório sai exatamente dos dados oficiais; **não** = não sai; **n/a** = não é número testável. A coluna \"Conclusão sustentada?\" avalia a inferência, não o número.\n")
L.append("| # | Alegação (conforme o resumo) | O que os dados mostram | Reproduz? | Conclusão sustentada? |\n|---|---|---|---|---|")
L.append(f"| 1 | O eleitorado apto das seções que fecharam depois das 17h são \"votos tardios\" | Nas {n(apt.secoes)} seções com encerramento ≥19h no relógio da urna, o eleitorado apto soma {n(apt.aptos)} e o comparecimento {n(apt.comparecimento)} ({n(apt.pct_comparecimento_sobre_aptos,1)}% dos aptos). Os logs medem os votos efetivamente computados depois do horário nominal: " + (f"estimativa nacional de {n(a5n.estimativa_total.iloc[0])} (IC95 {n(a5n.ic95_total_inf.iloc[0])} a {n(a5n.ic95_total_sup.iloc[0])}); nas seções de fechamento tardio, {n(a5n.votos_apos_nominal_em_L_medido.iloc[0])} nas medidas" if a5n is not None else "ver A5") + " | sim (a soma de aptos) | **Não**: aptos não são votos, e muitas dessas seções ficaram abertas sem registrar voto depois das 17h (A5) |")
L.append(f"| 2 | {n(c(2026,2,'de_17h01_a_17h15'))} seções fecharam entre 17h01 e 17h15 | Reproduzido com o relógio cru de `DT_ENCERRAMENTO`, com exterior: {n(c(2026,2,'de_17h01_a_17h15'))} (2022/T2: {n(c(2022,2,'de_17h01_a_17h15'))}; 2018/T2: {n(c(2018,2,'de_17h01_a_17h15'))}); 17h16 a 18h59: {n(c(2026,2,'de_17h16_a_18h59'))}; a partir das 19h: {n(c(2026,2,'a_partir_de_19h'))} | **sim** | O Código Eleitoral prevê o fechamento depois das 17h com os eleitores que já estavam na fila (art. 153); a faixa é normal em todos os anos |")
L.append(f"| 3 | {n(tot.loc[(2026,2),'biom_nh_total'])} liberações manuais | Soma de `QT_ELEI_BIOM_SEM_HABILITACAO` em 2026/T2 = **{n(tot.loc[(2026,2),'biom_nh_total'])}**; em 2022/T2 foram {n(tot.loc[(2022,2),'biom_nh_total'])} (queda de {n(100*(1-tot.loc[(2026,2),'biom_nh_total']/tot.loc[(2022,2),'biom_nh_total']),1)}%). O campo mede eleitores com biometria cadastrada não habilitados por ela; pelo log, o total manual é " + (f"{n(a5m.razao.iloc[0],2)} vez o do campo do BWeb (amostra)" if a5m is not None else "n/d") + " | **sim** | **Não** é número de votos nem de votos de Lula; a quantidade caiu 14% desde 2022 |")
L.append(f"| 4 | Correlação entre liberação manual e voto em Lula | Sem controle, a associação dentro do mesmo local é igual nos dois turnos de 2026 (0,074 e 0,070) e maior que em 2022. Condicionando no voto da seção no 1º turno, cai a 0,002 (2022: 0,016): o 2º turno não acrescenta nada (Fase 1, H1) | n/a (sem coeficiente no original) | **Não**: a relação já existe no 1º turno |")
b, rj, sp, pe, pb, se = (uf.loc[u] for u in ("BA", "RJ", "SP", "PE", "PB", "SE"))
L.append(f"| 5 | Bahia: seções que fecharam depois das 19h deram 72,31% a Lula, contra 71,31% no estado | **{n(b.lula_pct_nas_tardias,2)}%** contra **{n(b.lula_pct_no_estado,2)}%** ({n(b.secoes_tardias_relogio_cru)} seções, relógio cru): reproduz exatamente (+{n(b.diferenca_pp,2)} p.p.). Nos outros estados com seções tardias a diferença muda de sinal: RJ {n(rj.diferenca_pp,2)}, PE {n(pe.diferenca_pp,2)}, SE {n(se.diferenca_pp,2)}, PB {n(pb.diferenca_pp,2)}, SP +{n(sp.diferenca_pp,2)} p.p. Dentro do mesmo local e com o 1º turno como controle, o efeito de fechar tarde é {n(100*h4l.coef_pp/100,3)} p.p. (erro padrão {n(h4l.ep_pp,3)}) | **sim** | **Não**: +1 p.p. numa UF, com sinal contrário em outras, está dentro da variação geográfica comum |")
L.append(f"| 6 | Seções unânimes | Seções com ≥30 votos válidos e ≥90% para um candidato: PT {n(un.loc[2026,'pt_ge90'])} (2022: {n(un.loc[2022,'pt_ge90'])}), oponente {n(un.loc[2026,'oponente_ge90'])} (2022: {n(un.loc[2022,'oponente_ge90'])}); 100%: PT {n(un.loc[2026,'pt_100'])} (2022: {n(un.loc[2022,'pt_100'])}), oponente {n(un.loc[2026,'oponente_100'])} (2022: {n(un.loc[2022,'oponente_100'])}). Seções unânimes são esperadas em votação polarizada e concentrada | sim (contagens) | **Não**: caíram para o PT e subiram para o oponente em relação a 2022; sem placebo no original |")
L.append("| 7 | Benford | O qui-quadrado do primeiro dígito é enorme em todos os anos e para os dois candidatos (2022: 288.854 e 238.000; 2026: 297.064 e 273.600; p ≈ 0), o que mostra que o teste não discrimina em seções de tamanho limitado (literatura: Deckert, Myagkov e Ordeshook 2011; Mebane 2011). Último dígito (Beber e Scacco 2012) e percentuais inteiros (Kobak 2016): sem excesso (Fase 1, H8) | sim (qui-quadrado grande) | **Não** |")
L.append("| 8 | \"Sem autor, sem código\" | Este documento e o repositório publicam a autoria (ou a ausência dela, declarada), código, dados de origem e hashes | n/a | n/a |")
L.append("| 9 | As variáveis usadas não medem presença de fiscais | Correto: nenhuma variável do BWeb mede fiscais. Esta auditoria também não mede (limite declarado) | n/a | n/a |")
L.append("| 10 | A prorrogação foi por decisão monocrática, a primeira da história | Decisão do Min. Zanin documentada pela imprensa ([Base legal](base-legal.md)); \"primeira da história\" **não verificado** | parcial | n/a |")
L.append("| 11 | 34.330 eleitores votaram depois das 17h (levantamento da imprensa) | " + (f"Estimativa a partir dos logs: {n(a5n.estimativa_total.iloc[0])} (IC95 {n(a5n.ic95_total_inf.iloc[0])} a {n(a5n.ic95_total_sup.iloc[0])}); mesma ordem de grandeza, e inclui votantes com senha na fila (art. 153)" if a5n is not None else "ver A5") + " | compatível | **Não** é suficiente para alterar a margem de 4.430.191 |")
L.append("| 12 | \"Apagão de 72 horas\" nos dados, passaportes cancelados em 7 minutos, PF, Banco Master, Trump, mídia chinesa | Nenhum desses itens é testável com os dados usados aqui nem tem fonte nesta auditoria | **não avaliado** | **não avaliado** |")
L.append("\n**Síntese.** Dos números do relatório que são testáveis com dado oficial, os que são contagens (339.593 seções, 8,6 milhões, os percentuais da Bahia, as seções unânimes) reproduzem. As conclusões que o relatório tira deles não se sustentam: aptos não são votos, a liberação manual não é voto e não cresceu, a diferença da Bahia muda de sinal entre estados e some dentro do mesmo local, e a unanimidade não excede 2022.\n")
open(os.path.join(RAIZ, "docs", "relatorio-original.md"), "w", encoding="utf-8").write("\n".join(L))
print("escrito docs/relatorio-original.md")
